// Locale registry for The Latent Liturgy.
// `voice` = a narrator track in the artist's cloned voice exists (generated by scripts/voiceover.mjs).

export interface LocaleDef {
  code: string
  name: string // native name
  english: string
  rtl?: boolean
  /** Name used when instructing the LLM which language to answer in */
  llm: string
}

