export const LOCALE_CODES = LOCALES.map(l => l.code)
export const DEFAULT_LOCALE = 'en'
export const SOURCE_LOCALES = ['en', 'pl'] // hand-written; everything else is machine-translated from `en`

export function getLocale(code: string): LocaleDef {
  return LOCALES.find(l => l.code === code) ?? LOCALES[0]
}

/** Pick the best supported locale for a BCP-47 tag list (navigator.languages). */
export function matchLocale(tags: readonly string[] | undefined): string {
  if (!tags) return DEFAULT_LOCALE
  for (const tag of tags) {
    const lower = tag.toLowerCase()
    const exact = LOCALES.find(l => l.code === lower)
    if (exact) return exact.code
    const base = lower.split('-')[0]
    if (base === 'no' || base === 'nn') return 'nb'
    const partial = LOCALES.find(l => l.code === base)
    if (partial) return partial.code
  }
  return DEFAULT_LOCALE
}

/** Feature packages that ship their own i18n/<lang>.json next to their code. */
export const FEATURE_NAMESPACES = ['curator', 'guide', 'community', 'archaeology'] as const
